// Writes js/config/firebase-config.js from the FIREBASE_WEB_CONFIG secret (JSON).
// Only the known Firebase keys are copied (no excess data); missing keys fail the build.
import { writeFileSync } from 'node:fs';
import { REQUIRED_FIREBASE_KEYS, isFirebaseConfigured } from '../../js/core/config-check.js';

let parsed;
try {
  parsed = JSON.parse(process.env.FIREBASE_WEB_CONFIG ?? '');
} catch {
  console.error('FIREBASE_WEB_CONFIG is not valid JSON.');
  process.exit(1);
}

const config = Object.fromEntries(REQUIRED_FIREBASE_KEYS.map((key) => [key, String(parsed?.[key] ?? '').trim()]));
if (!isFirebaseConfigured(config)) {
  console.error(`FIREBASE_WEB_CONFIG must contain: ${REQUIRED_FIREBASE_KEYS.join(', ')}`);
  process.exit(1);
}

const source = `// Generated by the deploy workflow from the FIREBASE_WEB_CONFIG secret.
export const firebaseConfig = Object.freeze(${JSON.stringify(config, null, 2)});
`;
writeFileSync(new URL('../../js/config/firebase-config.js', import.meta.url), source);
console.log('Firebase web config written.');
